        if len(comp)<9: continue
        cur=set(comp); seq=[]
        while True:
            o,inner=layers(list(cur))
            seq.append((g[o[0][0]][o[0][1]],list(o)))
            cur=set(inner)
            if not inner: break
        n=len(seq)
        for y,x in sorted(cur|set(sum([s[1] for s in seq],[]))):
            pass
        # assign per depth via ring cells themselves
        for idx,(c,ringcells) in enumerate(seq[::-1]):
