def get_d(g):
    # per connected component, ring depths per cell
    D={}
    for comp in components(g):
        if len(comp)<9: continue
        rem=set(comp); dd={}
        d=0
        while True:
            o,inner=layers(list(rem))
            for c in o:
                if c not in dd: dd[c]=d
                dd.setdefault(c,d)
            if not inner: break
            d+=1; rem=set(inner)
        for c in dd: D.setdefault(c,d)
    return D

