# Key: rings aren't single-color comps; the 7s form two rings (row2+row3 vs deeper). Instead of component-peel, use bbox ring decomposition of each component's bounding box, taking colors from grid cells present on each perimeter ring.
def solve(g):
    res=[row[:] for row in g]
    def box(cells):
        ys=[c[0] for c in cells]; xs=[c[1] for c in cells]
        return min(ys),max(ys),min(xs),max(xs)
    for comp in components(g):
        if len(comp)<9: continue
        y0,y1,x0,x1=box(comp)
        # iterate over all cells inside bbox
        rem=set((y,x) for y in range(y0,y1+1) for x in range(x0,x1+1))
        seq=[]
        while True:
            cur=rem - {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if y!=y0 and y!=y1 and x!=x0 and x!=x1}
            if not cur: break
            col=g[y0][x0]
            seq.append((col,list(cur)))
            rem={(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if y!=y0 and y!=y1 and x!=x0 and x!=x1}
            # shrink: move inward
            y0+=1;y1-=1;x0+=1;x1-=1
            if y0>y1 or x0>x1: break
        n=len(seq)
        for idx,(col,cells) in enumerate(seq):
            newc=seq[n-1-idx][0]
            for y,x in cells:
                res[y][x]=newc
    return res

